import { Link } from "react-router-dom";
import { Bell, BellOff, Heart, LogIn, MessageCircle, ShieldOff, UserPlus, VolumeX } from "lucide-react";
import { apiFetch, clearApiCache } from "../api.js";
import { friendLabel } from "../utils/format.js";
import { Avatar, EmptyState, PresencePill, UserMini } from "./ui.jsx";

export function ProfileActions({ ctx, user, onChanged }) {
  const followed = Boolean(user.followed_by_me);

  async function follow() {
    try {
      await apiFetch(`/api/users/${user.id}/follow`, {
        method: "POST",
        body: JSON.stringify({ following: !followed }),
      });
      clearApiCache("/api/users");
      clearApiCache("/api/feed");
      onChanged?.();
    } catch (error) {
      ctx.showToast(error.message, "error");
    }
  }

  async function friend() {
    try {
      await apiFetch(`/api/users/${user.id}/friend-request`, { method: "POST" });
      clearApiCache("/api/users");
      clearApiCache("/api/friends");
      onChanged?.();
    } catch (error) {
      ctx.showToast(error.message, "error");
    }
  }

  // Per-follow notification mute, 2026-10-11 (see routes.lua's
  // M.set_follow_mute) -- distinct from unfollowing: stays in the
  // following list, just stops generating a notification per new upload.
  async function toggleFollowMute() {
    try {
      await apiFetch(`/api/users/${user.id}/follow-mute`, {
        method: "PATCH",
        body: JSON.stringify({ muted: !user.follow_notifications_muted }),
      });
      clearApiCache("/api/users");
      onChanged?.();
    } catch (error) {
      ctx.showToast(error.message, "error");
    }
  }

  async function block(kind) {
    const label = kind === "mute" ? "mute" : "block";
    if (!window.confirm(`Are you sure you want to ${label} @${user.username}?`)) return;
    try {
      await apiFetch(`/api/users/${user.id}/block`, {
        method: "POST",
        body: JSON.stringify({ kind, active: true }),
      });
      clearApiCache("/api/users");
      clearApiCache("/api/feed");
      ctx.showToast(`@${user.username} ${label}d.`, "success");
      onChanged?.();
    } catch (error) {
      ctx.showToast(error.message, "error");
    }
  }

  if (!ctx.user) return <Link className="button-link" to="/login"><LogIn size={16} />Login</Link>;
  return (
    <div className="profile-actions">
      <button type="button" onClick={follow}><Heart size={16} />{followed ? "Unfollow" : "Follow"}</button>
      {followed ? (
        <button type="button" title={user.follow_notifications_muted ? "Unmute notifications" : "Mute notifications"} onClick={toggleFollowMute}>
          {user.follow_notifications_muted ? <BellOff size={16} /> : <Bell size={16} />}
          {user.follow_notifications_muted ? "Unmute" : "Mute"}
        </button>
      ) : null}
      <button type="button" onClick={friend} disabled={["friends", "pending_out", "self"].includes(user.friend_status)}><UserPlus size={16} />{friendLabel(user.friend_status)}</button>
      {user.friend_status !== "self" ? <Link className="button-link" to="/messages" state={{ user }}><MessageCircle size={16} />Message</Link> : null}
      {user.friend_status !== "self" ? <button type="button" title="Mute" onClick={() => block("mute")}><VolumeX size={16} />Mute</button> : null}
      {user.friend_status !== "self" ? <button type="button" className="danger" title="Block" onClick={() => block("block")}><ShieldOff size={16} />Block</button> : null}
    </div>
  );
}

export function UserCard({ ctx, user, onChanged }) {
  function refreshUserState() {
    clearApiCache("/api/users/search");
    onChanged?.();
  }
  return (
    <article className="user-card">
      <Link className="avatar-link" to={`/users/${user.username}`}><Avatar user={user} large /></Link>
      <div>
        <Link to={`/users/${user.username}`}><h3>{user.display_name || user.username}</h3></Link>
        <PresencePill user={user} />
        <p>@{user.username}{user.profile_headline ? ` / ${user.profile_headline}` : ""}</p>
      </div>
      <div className="profile-actions user-card-actions">
        <Link className="button-link" to={`/users/${user.username}`}>View Profile</Link>
        <ProfileActions ctx={ctx} user={user} onChanged={refreshUserState} />
      </div>
    </article>
  );
}

export function FriendColumn({ title, rows, action }) {
  return (
    <div className="side-box">
      <div className="section-head"><h2>{title}</h2><span>{rows.length}</span></div>
      {rows.map((row) => (
        <article className="friend-request" key={row.id}>
          <UserMini user={row.user || row} />
          {action(row)}
        </article>
      ))}
      {!rows.length ? <EmptyState title="None" /> : null}
    </div>
  );
}
